<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue';
import {request} from '../store';
import CloudAccounts from './CloudAccounts.vue';
import {PendingServerWriteJournal,unwrapServerResult,packStatusLabel,reportStatusLabel,type AdminServerView,type ManagedPack,type ServerStatus} from '../../../../dispatch-core/src/main/typescript/server-contract';
const emit=defineEmits<{enabled:[boolean]}>();
const live=ref(false),enabled=ref(false),view=ref<AdminServerView|null>(null),busy=ref(false),error=ref(''),notice=ref('');
const form=reactive({name:'',fileName:'',sizeBytes:0,gameVersion:'1.20.6',loader:'Fabric'}),confirmation=reactive<Record<string,string>>({});
const targetType=ref<'group'|'player'>('group'),targetId=ref('default');let alive=true;
const journal=new PendingServerWriteJournal('admin',window.sessionStorage),pending=ref(journal.pending);
const blocked=computed(()=>busy.value||!!pending.value||!!journal.problem);
async function api<T>(path:string,body?:Record<string,unknown>){return unwrapServerResult<T>(await request('/api/server'+path,body===undefined?'GET':'POST',body));}
async function run(path?:string,body?:Record<string,unknown>,retry=false){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{
 const operation=path?journal.begin(path,body??{}):retry?journal.pending:null;pending.value=journal.pending;
 if(operation){await api(operation.path,operation.body);journal.completed();pending.value=null;if(alive)notice.value='模拟操作完成。没有上传ZIP内容或更改远端服务。';}
 const data=await api<AdminServerView>('/view');if(alive)view.value=data;
 }catch(e){if(path||retry)journal.failed(e);if(alive)error.value=e instanceof Error?e.message:'连接不上，请保留现场';}finally{pending.value=journal.pending;if(alive)busy.value=false;}}
function selected(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file){form.fileName=file.name;form.sizeBytes=file.size;if(!form.name)form.name=file.name.replace(/\.zip$/i,'');}}
function packAction(path:string,pack:ManagedPack,extra:Record<string,unknown>={}){void run(path,{packId:pack.id,revision:pack.revision,...extra});}
onMounted(async()=>{try{const status=await api<ServerStatus>('/status');if(!alive)return;enabled.value=status.enabled;emit('enabled',status.enabled);live.value=status.source==='LIVE';if(enabled.value&&!live.value)await run();}catch(e){if(alive)error.value=e instanceof Error?e.message:'无法读取服务器模式';}});
onBeforeUnmount(()=>{alive=false;});
</script>
<template>
 <CloudAccounts v-if="enabled&&live"/>
 <section v-else-if="enabled" class="stage server-console" aria-label="离线运营演练台">
  <header class="server-admin-heading"><div><span class="mock-label">MOCK · 离线演练</span><h1>玩家与整合包</h1><p>连接两端的操作流程。当前只记录ZIP元信息，账号不验证真实密码。</p></div><button data-server-admin-refresh :disabled="busy" @click="run()">{{busy?'正在处理…':'刷新 / 复查'}}</button></header>
  <p v-if="error" class="server-error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
  <p v-if="pending||journal.problem" class="server-error" role="status">{{journal.problem||'有未决操作，新增写入已暂停。刷新只读取结果，不会再次提交。'}}<button v-if="pending" :disabled="busy" data-server-admin-retry @click="run(undefined,undefined,true)">使用原操作编号重试</button></p>
  <template v-if="view"><div class="server-summary"><article><strong>{{view.players.length}}</strong><span>演练玩家</span></article><article><strong>{{view.packs.filter(p=>p.status==='PUBLISHED').length}}</strong><span>模拟发布</span></article><article><strong>{{view.players.filter(p=>p.report).length}}</strong><span>受管包报告</span></article></div>
   <section class="server-admin-card"><h2>玩家与分组</h2><p>分组由管理端决定；自己的整合包、存档和游戏凭据不在此列表。</p><div class="server-table"><table><thead><tr><th>玩家</th><th>所属组</th><th>最近受管包结果</th></tr></thead><tbody><tr v-for="player in view.players" :key="player.id" :data-server-player="player.username"><td><strong>{{player.displayName}}</strong><small>@{{player.username}}</small></td><td><select :value="player.groupId" :aria-label="player.username+'所属组'" :disabled="blocked" @change="run('/set-group',{playerId:player.id,revision:player.revision,groupId:($event.target as HTMLSelectElement).value})"><option v-for="group in view.groups" :key="group.id" :value="group.id">{{group.name}}</option></select></td><td>{{reportStatusLabel(player.report?.status??'')}}<small v-if="player.report">MOCK · {{player.report.updatedAt}}</small></td></tr></tbody></table><p v-if="!view.players.length">玩家端注册演练账号后，点击刷新。</p></div></section>
   <section class="server-admin-card"><h2>整合包上传演练</h2><p>选取ZIP仅读取名称与大小，不上传内容、解压、验签或执行内附程序。</p><fieldset :disabled="blocked"><div class="server-form"><label>ZIP文件<input type="file" accept=".zip" data-mock-upload-file @change="selected"/></label><label>整合包名称<input v-model="form.name" maxlength="100" data-mock-pack-name/></label><label>游戏版本<input v-model="form.gameVersion" maxlength="64"/></label><label>加载器<select v-model="form.loader"><option>原版</option><option>Fabric</option><option>Forge</option><option>NeoForge</option><option>Quilt</option></select></label></div><p v-if="form.fileName">{{form.fileName}} · {{form.sizeBytes.toLocaleString()}} 字节 · 元信息</p><button class="accent" data-mock-upload :disabled="!form.name||!form.fileName||!form.sizeBytes||!form.fileName.toLowerCase().endsWith('.zip')" @click="run('/upload',{...form})">生成模拟导入预览</button></fieldset></section>
   <section class="server-admin-card"><h2>发布与下发</h2><div class="server-target"><label>分配类型<select v-model="targetType" @change="targetId=targetType==='group'?'default':view?.players[0]?.id??''"><option value="group">玩家组</option><option value="player">单个玩家</option></select></label><label>目标<select v-model="targetId" data-mock-target><template v-if="targetType==='group'"><option v-for="g in view.groups" :key="g.id" :value="g.id">{{g.name}}</option></template><template v-else><option v-for="p in view.players" :key="p.id" :value="p.id">{{p.displayName}}</option></template></select></label></div>
    <p v-if="!view.packs.length">尚无模拟整合包，先选择ZIP创建预览。</p><article v-for="pack in view.packs" :key="pack.id" class="server-pack-row" :data-admin-pack="pack.id"><header><div><h3>{{pack.name}}</h3><p>{{pack.gameVersion}} · {{pack.loader}} · {{packStatusLabel(pack.status)}} · 修订 {{pack.revision}}</p><small>MOCK · {{pack.fileName}} · 已分配 {{pack.assignments.length}} 个目标</small></div><span class="mock-label">模拟版本</span></header><div class="server-pack-actions"><button v-if="pack.status==='PREVIEW'||pack.status==='UNLISTED'" data-mock-publish :disabled="blocked" @click="packAction('/publish',pack)">模拟发布</button><button v-if="pack.status==='PUBLISHED'" data-mock-assign :disabled="blocked||!targetId" @click="packAction('/assign',pack,{targetType,targetId})">分配到所选目标</button><button v-if="pack.status==='PUBLISHED'" :disabled="busy" data-mock-unlist @click="packAction('/unlist',pack)">下架</button><button v-if="pack.status==='DELETED'" :disabled="busy" data-mock-restore @click="packAction('/restore',pack)">从保留区恢复</button></div><div v-if="pack.status!=='DELETED'" class="server-delete"><input v-model="confirmation[pack.id]" :aria-label="pack.name+'删除确认'" placeholder="输入整合包名称确认" :disabled="busy"/><button class="danger" data-mock-delete :disabled="blocked||confirmation[pack.id]!==pack.name" @click="packAction('/delete',pack,{confirmation:confirmation[pack.id]})">移到保留区</button></div></article>
   </section><footer>仅演练，未连接服务器。删除模拟包不会删除玩家本地实例或存档。真实文件上传、签名更新、认证与Minecraft另行验收。</footer>
  </template>
 </section>
</template>
<style scoped>
.server-console{max-width:1400px}.server-admin-heading,.server-pack-row header{display:flex;justify-content:space-between;align-items:center;gap:18px}.mock-label{display:inline-block;font-size:12px;padding:6px 10px;border-radius:8px;background:#d69d3720;color:var(--accent,#af8d4c)}.server-console p{opacity:.78;line-height:1.7}.server-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.server-summary article{padding:20px;border:1px solid #8883;border-radius:14px;display:grid;gap:10px}.server-summary strong{font-size:28px}.server-admin-card{padding:24px;border:1px solid #8883;border-radius:16px;margin:20px 0}.server-admin-card h2{margin:0 0 12px}.server-table{overflow:auto}.server-table table{border-collapse:collapse;width:100%;min-width:500px}.server-table td,.server-table th{padding:14px;text-align:left;border-bottom:1px solid #8882}.server-console small{display:block;opacity:.65;margin-top:6px}.server-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.server-form label,.server-target label{display:grid;gap:8px}.server-console input,.server-console select{width:100%;max-width:100%;padding:10px;border:1px solid #8885;border-radius:8px;background:var(--panel,#272727);color:inherit}.server-console fieldset{padding:0;border:0;min-width:0}.server-pack-row{padding:20px;border-top:1px solid #8883;margin-top:18px}.server-target,.server-pack-actions,.server-delete{display:flex;gap:12px;flex-wrap:wrap;margin:15px 0}.server-delete input{max-width:280px}.server-error{color:#ed8f8f;border:1px solid #b55;padding:14px;border-radius:10px}.server-console footer{opacity:.6;line-height:1.8;font-size:12px}.server-console button{min-height:38px;padding:9px 14px}.server-console button:disabled{opacity:.4}@media(max-width:900px){.server-form{grid-template-columns:1fr}.server-admin-heading{flex-wrap:wrap}.server-admin-card{padding:16px}}
</style>
